// AUTO-GENERATED by scripts/50_export_dashboard_data.py — do not edit by hand.
// Three tables backing the /non-accruals page:
//
//  currentNonAccruals — every NA position in the latest reliable quarter
//    per BDC. Fair value / cost / par are converted to MILLIONS of real USD.
//
//  nonAccrualFlow — issuer × normalized borrower × instrument aggregates.
//    These are observed aggregate status changes, not verified facility events.
//    Maturity is an amendable term, not an identity key. Homogeneous, known
//    states in consecutive quarters can produce new_na/cured. Mixed/unknown
//    components, missing observations and gaps remain separate event classes.
//    A disappearance is removed_unknown; it is never evidence of cure.
//    Source row ID sets retain lineage; aggregate exposure is counted once.
//
//  crossIssuerDisagreement — borrowers held by 2+ covered BDCs in the
//    latest quarter where at least one BDC flagged the loan non-accrual
//    AND at least one did not. Useful for spotting cross-issuer mark
//    rebellions.
//
// Positions whose non-accrual status is unknown for the quarter are left
// out of is_non_accrual aggregations (never counted as performing).

export interface CurrentNonAccrual {
  ticker: string;
  period_end: string;
  company: string;
  company_norm: string;
  industry: string | null;
  investment_type: string | null;
  maturity_date: string | null;
  fv_m: number;       // USD millions
  cost_m: number;     // USD millions
  par_m: number;      // USD millions (0 for equity)
  mark_at_par: number | null;   // 0..1 (null when par not available)
}

export interface NonAccrualFlowEvent {
  ticker: string;
  period_end: string;          // current quarter being reported
  prior_period_end: string;
  event: "new_na" | "cured" | "first_observed_na" | "removed_unknown" | "unknown_status";
  event_id: string;
  grain: "borrower_instrument_aggregate";
  status_reason: string;
  cur_source_row_ids: string[];
  prv_source_row_ids: string[];
  prv_cost_m: number | null;
  company: string;
  company_norm: string;
  investment_type: string | null;
  maturity_date: string | null;
  cur_fv_m: number | null;     // aggregate FV; null if absent or incomplete
  prv_fv_m: number | null;     // fv in prior quarter (null if new position)
  cost_m: number | null;        // aggregate current cost, counted once
}

export interface CrossIssuerDisagreement {
  company_norm: string;
  display_name: string;            // most recent display variant
  period_end: string;
  n_holders: number;
  n_holders_na: number;
  total_fv_m: number;
  total_fv_na_m: number;
  holders: Array<{ ticker: string; is_non_accrual: boolean; fv_m: number; mark_at_par: number | null }>;
}

